<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';
import {NAlert,NButton,NEmpty,NSelect,NSpace,NTag,NPopconfirm,NInput} from 'naive-ui';
import {api,ApiError,errorMessage} from '../../shared/api';
import type {Workspace} from '../../shared/api';
const props=defineProps<{workspace:Workspace;disabled:boolean}>();const emit=defineEmits<{busyChanged:[boolean];sessionExpired:[];invite:[]}>();
type Member={id:string;displayName:string;username:string;role:'owner'|'admin'|'member';status:string;version:number};
const rows=ref<Member[]>([]),roles=ref<Record<string,string>>({}),busy=ref(false),loaded=ref(false),error=ref('');const query=ref(''),statusFilter=ref<'all'|'active'|'disabled'>('all');
const filtered=computed(()=>rows.value.filter(row=>(statusFilter.value==='all'||row.status===statusFilter.value)&&(!query.value.trim()||`${row.displayName} ${row.username}`.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase()))));
let controller=new AbortController(),generation=0;
watch(busy,v=>emit('busyChanged',v),{flush:'sync'});
async function read(signal:AbortSignal){const result=await api<{members:Member[]}>(`/workspaces/${encodeURIComponent(props.workspace.id)}/members`,signal);if(!signal.aborted){rows.value=result.members;roles.value=Object.fromEntries(result.members.map(r=>[r.id,r.role]));loaded.value=true;}}
async function run(fn:(signal:AbortSignal)=>Promise<void>){if(busy.value||props.disabled)return;const version=generation,signal=controller.signal;busy.value=true;error.value='';try{await fn(signal);}catch(e){if(!signal.aborted&&version===generation){error.value=errorMessage(e);if(e instanceof ApiError&&e.status===401)emit('sessionExpired');if(e instanceof ApiError&&e.status===403)rows.value=[];}}finally{if(!signal.aborted&&version===generation)busy.value=false;}}
async function patch(item:Member,status=false){await run(async signal=>{await api(`/workspaces/${encodeURIComponent(props.workspace.id)}/members/${encodeURIComponent(item.id)}`,signal,{expectedVersion:item.version,...(status?{enabled:item.status!=='active'}:{role:roles.value[item.id]})},'PATCH');await read(signal);});}
watch(()=>props.workspace.id,()=>{generation++;controller.abort();controller=new AbortController();busy.value=false;loaded.value=false;rows.value=[];query.value='';statusFilter.value='all';void run(read);},{immediate:true});onUnmounted(()=>{generation++;controller.abort();emit('busyChanged',false);});
</script>
<template><section class="members">
 <div class="member-heading"><p class="field-note">管理谁可以加入和使用此工作区。</p><NSpace><NButton :disabled="busy || disabled" @click="run(read)">刷新成员</NButton><NButton type="primary" :disabled="busy || disabled" @click="emit('invite')">邀请成员</NButton></NSpace></div>
 <NAlert v-if="error" type="error" role="alert">{{ error }}</NAlert><p v-if="busy && !loaded" role="status">正在读取成员…</p>
 <div v-if="loaded && !error && rows.length" class="member-filters"><NInput v-model:value="query" clearable placeholder="搜索成员或账号" :input-props="{ 'aria-label': '搜索成员' }" /><NSelect v-model:value="statusFilter" aria-label="成员状态" :virtual-scroll="false" :options="[{ label: '全部成员', value: 'all' }, { label: '活跃', value: 'active' }, { label: '已禁用', value: 'disabled' }]" /></div>
 <NEmpty v-if="loaded && !busy && !error && !rows.length" description="暂无成员" /><NEmpty v-else-if="loaded && !error && rows.length && !filtered.length" description="没有符合条件的成员" />
 <div v-if="filtered.length" class="member-table-wrap"><table class="member-table"><thead><tr><th scope="col">成员</th><th scope="col">账号</th><th scope="col">角色</th><th scope="col">状态</th><th scope="col">操作</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td data-label="成员"><strong>{{ item.displayName }}</strong><span v-if="item.id === workspace.memberId" class="field-note"> · 你</span></td><td data-label="账号">@{{ item.username }}</td><td data-label="角色">{{ item.role === 'owner' ? '所有者' : item.role === 'admin' ? '管理员' : '成员' }}</td><td data-label="状态"><NTag size="small" :bordered="false" :type="item.status === 'active' ? 'success' : 'default'">{{ item.status === 'active' ? '活跃' : '已禁用' }}</NTag></td><td data-label="操作"><span v-if="item.role === 'owner'">—</span><NSpace v-else :size="8"><NSelect :value="roles[item.id] ?? item.role" @update:value="value => { roles[item.id] = String(value) }" class="member-role" :aria-label="`${item.displayName}角色`" :options="[{ label: '管理员', value: 'admin' }, { label: '成员', value: 'member' }]" :disabled="busy || disabled || item.id === workspace.memberId" /><NButton size="small" :disabled="busy || disabled || roles[item.id] === item.role || item.id === workspace.memberId" @click="patch(item)">保存角色</NButton><NPopconfirm @positive-click="patch(item,true)"><template #trigger><NButton size="small" :disabled="busy || disabled || item.id === workspace.memberId">{{ item.status === 'active' ? '禁用成员' : '恢复成员' }}</NButton></template>禁用“{{ item.displayName }}”后，该成员将无法使用当前工作区；已有任务和历史保留。</NPopconfirm></NSpace></td></tr></tbody></table></div>
</section></template>
<style scoped>.members{display:grid;gap:1rem;min-width:0}.member-heading{display:flex;justify-content:space-between;gap:1rem;align-items:center}.member-heading p{margin:0}.member-filters{display:grid;grid-template-columns:minmax(12rem,28rem) 11rem;gap:1rem;justify-content:space-between}.member-table-wrap{overflow:auto;border:1px solid var(--subtle);border-radius:.75rem;background:var(--surface)}.member-table{width:100%;border-collapse:collapse;font-size:.875rem}.member-table th,.member-table td{text-align:left;padding:1rem;vertical-align:middle;border-bottom:1px solid var(--subtle)}.member-table th{background:var(--background);color:var(--muted);font-weight:500;white-space:nowrap}.member-table tr:last-child td{border-bottom:0}.member-table td{overflow-wrap:anywhere}.member-role{width:8rem}.member-table td:last-child{min-width:20rem}@media(max-width:47.5rem){.member-heading{align-items:flex-start;flex-wrap:wrap}.member-filters{grid-template-columns:1fr}.member-table,.member-table tbody,.member-table tr{display:block}.member-table thead{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.member-table tr{padding:.75rem 1rem;border-bottom:1px solid var(--subtle)}.member-table tr:last-child{border-bottom:0}.member-table tr td{display:flex;justify-content:space-between;gap:1rem;padding:.5rem 0;border:0}.member-table tr td:before{content:attr(data-label);color:var(--muted);flex:none}.member-table tr td:first-child:before{display:none}.member-table tr td:last-child{min-width:0;display:block}.member-table tr td:last-child:before{display:none}.member-role{width:8rem}}</style>
